CREATE OR REPLACE VIEW `vwcogestorno` AS select date_format(`p`.`data_status`,'%Y-%m') AS `mese`,count(0) AS `n`,sum((if((`p`.`entrata_uscita` = 'Entrata'),1,0) * `p`.`importo`)) AS `storno_entrata`,sum((if((`p`.`entrata_uscita` = 'Entrata'),0,1) * `p`.`importo`)) AS `storno_uscita` from `provvigioni` `p` where (`p`.`status_compenso` = 'Pratica stornata') group by date_format(`p`.`data_status`,'%Y-%m') order by date_format(`p`.`data_status`,'%Y-%m') desc
